   hollow IN socket. Calm console design; route highlight only on actual intent.
   Compact always keeps the wires visible; expanded has more cable canvas. */@media(max-height:680px){
}
.route-choice[hidden]{display:none!important}
.route-choice{
 position:absolute;z-index:30;box-sizing:border-box;width:280px;
 border:1px solid #5c8090;border-radius:6px;background:#1b2d38;
 color:#cde0e8;padding:10px;box-shadow:0 8px 28px #0009,inset 0 1px #bfdbe41c;
 font:11px/1.4 'Segoe UI',Arial,sans-serif;
}
.route-choice-head{display:flex;justify-content:space-between;align-items:center;
 font-weight:650;color:#e5f6f8;font-size:12px;padding-bottom:7px;
 border-bottom:1px solid #56707a5c;}
.route-choice-head button{background:#283f4c;border:1px solid #486778;
 color:#d9ebed;border-radius:3px;width:25px;height:23px;cursor:pointer}
.route-choice-description{color:#aac4cc;font-size:10px;padding:9px 0}
.route-choice-option{display:flex;align-items:center;text-align:left;gap:9px;
 width:100%;padding:9px 8px;margin-top:5px;border:1px solid #42616c;
 border-radius:4px;background:#263c48;color:#e1f2ef;cursor:pointer}
.route-choice-option:hover{background:#315261;border-color:#9bc8c8}
.route-choice-option.primary{border-color:#4b9d7a;background:#244638}
.route-choice-option.primary:hover{background:#31634c}
.route-choice-option strong{font:600 11px/15px 'Segoe UI',Arial,sans-serif}
.route-choice-option small{display:block;color:#a8c7c9;font-size:10px;line-height:14px}
.route-choice-option .choice-symbol{font-size:20px;color:#a7eec5}
.route-choice-foot{color:#91b1b9;font-size:9px;padding-top:9px}
