@media(max-width:1100px){
 .console-body.wire-routing-v15 .wire-tray{gap:2px!important;padding-inline:2px!important}
 .console-body.wire-routing-v15 .wire-node-out,
 .console-body.wire-routing-v15 .wire-node-in{width:25px!important;min-width:25px!important;flex-basis:25px!important}
