/* V16: When BOTH expandable FX and SEND are closed, reclaim the blank
   upper volume for the calibrated fader even if ROUTE is still expanded.
   Any other upper combination retains the anchored lower deck. */
.console-body.collapsed-fx.collapsed-send .strip .pan-section,
.console-body.collapsed-fx.collapsed-send .section-rail>.rail-cell.pan{margin-top:0!important}
.console-body.collapsed-fx.collapsed-send .strip .fader-section,
.console-body.collapsed-fx.collapsed-send .section-rail>.rail-cell.fader{
 flex:1 1 var(--v13-fader-h)!important;height:auto!important;
 min-height:var(--v13-fader-h)!important;max-height:none!important;
}
/* Front edge: this slender, non-interactive seam sits OVER the metal
   compartments instead of disappearing beneath panel backgrounds. */
.console-body .strip{position:relative!important;isolation:isolate}
.console-body .strip::after{
 content:"";position:absolute;right:0;top:0;bottom:0;width:1px;
 background:#061722;box-shadow:-1px 0 #8babb538;
 z-index:15;pointer-events:none;
}
.console-body .strip.channel-dragging{opacity:.55!important}
.console-body .strip.channel-drop-before::before,
.console-body .strip.channel-drop-after::before{
 content:"";position:absolute;top:0;bottom:0;width:3px;
 background:#8ce3f1;z-index:18;pointer-events:none;
}
.console-body .strip.channel-drop-before::before{left:0}
.console-body .strip.channel-drop-after::before{right:0}
.console-body .strip-identity-top[draggable="true"]{cursor:grab}
.console-body .strip-identity-top[draggable="true"]:active{cursor:grabbing}

/* V16: the WIRE graph is an upper compartment. When SEND is folded
   the sockets and cable illustration are invisible, leaving only a
   clean 23px disclosure row; model fan-out remains untouched. */@media(max-height:680px){.console-body.wire-routing-v15.collapsed-send{--send-h:23px!important}}
.console-body.wire-routing-v15.collapsed-send .routing-wire-overlay{display:none!important}
