 font-style:normal!important;letter-spacing:0!important;
 color:#a0b7c1!important;background:#1d303a!important;
 border-left:2px solid #233640!important;
 text-shadow:none!important;transition:none!important;
 border-top:0!important;
}
.console-body.wire-routing-v13 .section-rail>.rail-cell.send{
 background:#182b35!important;color:#9aafb9!important;
}
.console-body .section-rail>.rail-cell[data-section].collapsed{
 background:#182934!important;color:#748e9b!important;
 border-left-color:#314a57!important;
 box-shadow:inset 1px 0 #536f7c30!important;
}
.console-body .section-rail>.rail-cell[data-section]:not(.collapsed){
 border-left-color:#8bcdd5!important;
