}
.console-body .section-rail>.rail-cell[data-section]:hover{
 background:#2a424d!important;color:#e3eff2!important;
}
.console-body .section-rail>.rail-cell[data-section]::after,
.console-body.wire-routing-v13 .section-rail>.rail-cell.send::after,
.console-body.wire-routing-v13.collapsed-send .section-rail>.rail-cell.send::after{
 content:""!important;display:block!important;
 position:absolute!important;right:2px!important;top:4px!important;
 width:3px!important;height:3px!important;
 border:solid currentColor!important;border-width:0 1px 1px 0!important;
 transform:rotate(45deg)!important;opacity:.75!important;
 background:transparent!important;font-size:0!important;
}
.console-body .section-rail>.rail-cell[data-section].collapsed::after,
.console-body.wire-routing-v13.collapsed-send .section-rail>.rail-cell.send::after{
