}
.console-body .section-rail .rail-cell.route,
.console-body .section-rail .rail-cell.fx,
.console-body .section-rail .rail-cell.send{
 padding:0 2px 0 0!important;justify-content:center!important;
}
/* The collapsed WIRE rack stays exactly 23px. FX/fader geometry is unchanged. */


/* V22 CLEAN HARDWARE KEY + SELECTION + FADER CONTRACT
   The material is intentionally smooth: one uninterrupted face gradient.
   A separate STATIC socket wrapper owns the hole, recess and overlaid metal
   bezel. Only the button child moves 1px. No blur or filter. This repairs
   the V20 wavy/zebra shading and the buried channel selection highlight. */

/* Thin internal light (not glowing) — no repeated bright/dark bands. */
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key) {
 background:linear-gradient(180deg,
   var(--am-hw-key-bright) 0%,
   var(--am-hw-key-face) 42%,
   var(--am-hw-key-deep) 100%)!important;
 box-shadow:var(--am-hw-key-relief)!important;
 filter:none!important;
 backdrop-filter:none!important;
 -webkit-backdrop-filter:none!important;
 transition:none!important;
}
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key):hover {
 filter:none!important;
}
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key):active:not(:disabled) {
 transform:translateY(1px)!important;
 box-shadow:var(--am-hw-key-flat)!important;
}
/* Static bezel structure deliberately resides OUTSIDE the button element.
   ::after has z-index 4 over button (z-index 2); pointer-events:none, and
   never inherits keycap's transform, MUTE state, or active/hover behavior. */





/* No rectangular mask over switch text: upper bezel is ONLY 1px edge,
   mounted in the parent frame, not a moving overlay on the cap. */
.console-body .strip .switch-section {
 align-items:flex-start!important;
}
/* V22 fader: keep original metal PNG, size it ~11% smaller; increase the
   full calibration travel consistently across master, channel and rail.
   FX absorbs up to 6px extra fader height only when viewport allows; short screens keep original dock. */
/* Selected channel border is ON TOP of every sub-panel, never buried.
   Reuse the existing root strip::after instead of adding DOM nodes or
   using strip's background/inset-box-shadow behind opaque children. */
.console-body .strip.selected {
 z-index:2!important;
}
.console-body .strip.selected::after {
 content:""!important;position:absolute!important;
 inset:0!important;width:auto!important;height:auto!important;
 z-index:60!important;pointer-events:none!important;
 border:2px solid var(--ch,#7ed5e4)!important;
 border-radius:0!important;
 background:transparent!important;

}
/* Preserve drag-drop insert indicators without suppressing selected rim. */
.console-body .strip.channel-drop-before::before,
.console-body .strip.channel-drop-after::before{z-index:61!important}
/* GPU budget: no blurred shading, translucent full-page overlays or
   per-strip will-change compositor promotion. Keep interactions responsive. */
.console-body .strip,.console-body .strip::after,
.console-body .strip .hw-switch-socket {
 will-change:auto!important;
 filter:none!important;
 backdrop-filter:none!important;
 -webkit-backdrop-filter:none!important;
}


/* V22: iconography faithfully traced from approved wire + FX references.
   Inline SVGs are single-pass vector paint; no icon fonts or image requests. */
.console-body .section-rail .rail-svg-icon{
 width:16px!important;height:16px!important;
 display:block;flex:none;overflow:visible;pointer-events:none;
 color:inherit;fill:currentColor;opacity:.94;
}
.console-body .section-rail .rail-cell.fx .rail-svg-icon{width:16px!important;height:16px!important}
.console-body .section-rail .rail-cell.send .rail-svg-icon{width:16px!important;height:16px!important}
.console-body .section-rail .rail-cell.route .rail-svg-icon{width:16px!important;height:16px!important}
.console-body .section-rail .rail-cell[data-section]:hover .rail-svg-icon{opacity:1}
.console-body .section-rail .rail-cell[data-section].collapsed .rail-svg-icon{opacity:.76}


/* V25 UX: compact physical WIRE, taller fader, thin selected rim,
   sharp offline Google Material SVG icons; all same strip+rail tokens. */
.console-body.wire-routing-v15:not(.collapsed-send){
 --send-h:112px!important;
}
@media(max-height:680px){
 .console-body.wire-routing-v15:not(.collapsed-send){--send-h:102px!important}
}/* Icons are inline Material vectors: independent of OS font fallback,
   external CDN, SVG filters and extra fonts; keep buttons tactile. */
.mi-svg{display:inline-block;vertical-align:middle;flex:0 0 auto;pointer-events:none}
.mixer-title .panel-sub{display:inline-flex;align-items:center;justify-content:center}
.route-choice-option .choice-symbol{display:inline-flex;align-items:center;justify-content:center}
#preview .mi-svg{margin-right:3px}


/* V27 narrow console QA: toolbar operations must never run into each
   other at laptop widths. Keep drop-down overflow visible. */
@media(max-width:1360px){
 .command-bar{gap:4px!important;padding-inline:5px!important;min-width:0!important}
 .command-bar>.toolbar-label{display:none!important}
 .command-bar>.sep{display:none!important}
 .command-bar>#bankSelect{width:clamp(104px,12vw,142px)!important;min-width:100px!important;max-width:142px!important;flex:0 1 auto!important}
 .command-bar>#densitySelect{width:102px!important;min-width:83px!important;max-width:105px!important;flex:0 1 auto!important}
 .command-bar>#sofTarget{width:74px!important;min-width:55px!important;max-width:85px!important;flex:0 1 auto!important}
 .command-bar>#sceneSelect{width:71px!important;min-width:52px!important;max-width:77px!important;flex:0 1 auto!important}
 .command-bar>#sofToggle{min-width:0!important;max-width:140px!important;overflow:hidden!important;text-overflow:ellipsis!important}
 .command-bar>.tool,.command-bar>.more-tools{flex-shrink:0!important}
 .command-bar>.tool:not(.bank-arrow){padding-inline:7px!important}
}
@media(max-width:1030px){
 .command-bar>#sofToggle{max-width:100px!important}
 .command-bar>#clearCue{max-width:77px!important;overflow:hidden!important;text-overflow:ellipsis!important}
}

/* V28 FADER HEIGHT — regain visual travel from unused FX whitespace.
   All strips and rail share --v13-fader-h, no change to knob asset or lower anchors. */
.console-body{--v13-fader-h:clamp(160px,calc(100dvh - 584px),530px)}
/* WIRE stays sharply painted: no blur, shared ferrule or SVG filters. */
.routing-wire-overlay path{filter:none!important;pointer-events:none}
